            os.chmod(temp,mode);os.replace(temp,path)
        finally:
            if os.path.exists(temp):os.unlink(temp)
    def config(keys,stage):
        return (''.join('ssl_session_ticket_key '+json.dumps(str(k))+';\n' for k in keys)+'add_header X-Ring '+json.dumps(stage)+' always;\n').encode()
    outcome={'status':'rejected','phase':phase,'changed':[],'restored':[],'error':None}
    snapshots=[];changed=[]
    target_report=local(report)
    protected_keys={local(old_key),local(new_key)}
    node_directories=[local(n['directory']) for n in nodes]
    if target_report in protected_keys or any(target_report.is_relative_to(d) for d in node_directories):raise ValueError('report must be separate from keys and node directories')
    try:
        if phase not in {'prepare','promote','retire'}:raise ValueError('unknown phase')
        for value in (now,retire_after):
            if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value):raise ValueError('finite policy clock required')
        if phase=='retire' and now<retire_after:raise ValueError('retirement window not reached')
        old_key,new_key=local(old_key),local(new_key)
        old,new=old_key.read_bytes(),new_key.read_bytes()
        if len(old)!=80 or len(new)!=80 or old[:16]==new[:16]:raise ValueError('distinct 80-byte ticket keys required')
        if any(stat.S_IMODE(p.stat().st_mode)&0o077 for p in [old_key,new_key]):raise ValueError('ticket key permissions too broad')
        states={'old':config([old_key],'old'),'prepare':config([old_key,new_key],'prepare'),
                'promote':config([new_key,old_key],'promote'),'retire':config([new_key],'retire')}
        predecessor={'prepare':'old','promote':'prepare','retire':'promote'}[phase]
        if not nodes or len({n['name'] for n in nodes})!=len(nodes):raise ValueError('unique named nodes required')
        paths=[]
        for node in nodes:
            path=local(node['directory'])/'ticket-keys.conf';paths.append(path)
            current=path.read_bytes()
