            snapshots.append((node,path,current,stat.S_IMODE(path.stat().st_mode)))
        if len(set(paths))!=len(paths) or target_report in paths or target_report in {old_key,new_key}:raise ValueError('overlapping output paths')
        # All nodes are preflighted before the first mutation.
        for node,path,current,mode in snapshots:
            if current==states[phase]:continue
            changed.append((node,path,current,mode))
            atomic(path,states[phase]);activate(node)
            outcome['changed'].append(node['name'])
        outcome['status']='committed' if changed else 'unchanged'
    except Exception as e:
        outcome['error']=type(e).__name__
        if changed:
            failures=[]
            for node,path,current,mode in reversed(changed):
                try:
                    if path.read_bytes()!=current or stat.S_IMODE(path.stat().st_mode)!=mode:atomic(path,current,mode)
