                except Exception as rollback:failures.append({'node':node['name'],'error':type(rollback).__name__})
            outcome['status']='rollback_failed' if failures else 'rolled_back'
            outcome['rollback_errors']=failures
    atomic(target_report,json.dumps(outcome,indent=2).encode())
